"use strict";
const $ = (id) => document.getElementById(id);
const params = new URLSearchParams(location.search);
const modules = {
 lab:{label:"임상병리검사",title:"임상병리검사 결과지",history:"임상검사 이력",right:"장비 검사 수신함",cap:1120,task:"혈청화학 검사"},
 chart:{label:"진료/차트",title:"진료 기록 · SOAP",history:"진료 이력",right:"참고 자료",cap:1040,task:"외래 진료"},
 dispensing:{label:"조제/처치",title:"조제·처치 수행 기록",history:"수행 이력",right:"수행 상세",cap:1120,task:"처방 조제"},
 imaging:{label:"영상",title:"영상검사 보고서",history:"영상검사 이력",right:"종합소견·첨부",cap:1280,task:"영상검사"},
 billing:{label:"수납",title:"청구 내역 확인",history:"수납 이력",right:"청구 확인",cap:1120,task:"청구서 확인"}
};
const fields = {};
let state = {module:modules[params.get("module")]?params.get("module"):"lab",vp:[1366,1440,1600,1920,2560].includes(Number(params.get("viewport")))?Number(params.get("viewport")):1920,mode:"compact",left:false,right:false,queue:true,current:false,latest:"right",scale:1,viewer:false};
let previousFocus=null, modalSide=null, toastTimer, measuredCenterWidth=0;
if(params.has("embed"))document.body.classList.add("embed");
const escapeHtml = (s) => String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
const field = (key, initial, multiline=false) => {const value=escapeHtml(fields[state.module+":"+key]??initial);return multiline?`<textarea data-field="${key}" aria-label="${key}">${value}</textarea>`:`<input data-field="${key}" aria-label="${key}" value="${value}">`;};
function meta(){return `<div class="meta-grid"><div><small>요청 일시</small><b>26.09.29 12:05</b></div><div><small>환자 정보</small><b>하루 · 가상 예시</b></div><div><small>요청자</small><b>예시 수의사</b></div><div><small>업무 상태</small><b>진행 중</b></div></div>`;}
function table(headers,rows){return `<div class="table-scroll" tabindex="0" role="region" aria-label="업무 표 · 필요 시 가로 스크롤"><table class="result-table"><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;}
function documentHtml(){
 const intro=meta();
 if(state.module==="lab")return intro+`<div class="filter-tabs"><b>전체 4</b><span>혈청화학 4</span><span>가상 결과</span></div><section class="section-box"><div class="section-head"><h3>혈청화학 검사 세트</h3><small>기본 간격 · 행 높이 유지</small></div>${table(["항목","결과값","단위","참고범위","판정","담당자"],[["칼슘 (Ca)",field("칼슘 결과값","9.8"),"mg/dL","8.5–12.0",'<span class="status">범위 내</span>',"예시 담당"],["알부민 (ALB)",field("알부민 결과값","3.2"),"g/dL","2.5–4.4",'<span class="status">범위 내</span>',"예시 담당"],["혈당 (GLU)",field("혈당 결과값","118"),"mg/dL","70–140",'<span class="status">범위 내</span>',"예시 담당"],["총단백 (TP)",field("총단백 결과값","6.4"),"g/dL","5.2–8.2",'<span class="status">범위 내</span>',"예시 담당"]])}</section><section class="section-box"><div class="section-head"><h3>검사결과 종합소견</h3><small>본문은 별도로 줄 길이 제한</small></div>${field("검사결과 종합소견","수신 결과와 현재 요청을 확인한 뒤 검토 예정입니다.",true)}</section>`;
 if(state.module==="chart")return intro+`<div class="filter-tabs"><b>SOAP</b><span>Assessment</span><span>Plan / Order</span></div><section class="section-box"><div class="section-head"><h3>현재 진료 기록</h3><small>문서 폭 1,040px · 본문 최대 40ic</small></div><label class="field-label">Subjective · 주관적 정보</label>${field("Subjective","보호자에게 내원 목적과 최근 변화를 확인합니다.",true)}<label class="field-label">Objective · 객관적 정보</label>${field("Objective","관찰 내용과 검사 결과를 기록합니다.",true)}</section><div class="callout">Order의 많은 열을 비교할 때는 넓게 보기로 전환. 기존 25개 열과 고정 열·가로 스크롤 계약은 그대로 유지하는 제안이야.</div>`;
 if(state.module==="dispensing")return intro+`<div class="filter-tabs"><b>조제</b><span>처치</span><span>수행 기록</span></div><section class="section-box"><div class="section-head"><h3>현재 수행 대상</h3><small>가상 품목 · 실제 처방 아님</small></div>${table(["품목","예정량","실조제량","보관","상태","담당자"],[["예시 조제품 A","10 mL",field("A 실조제량","10"),"별도 확인","준비 중","예시 담당"],["예시 조제품 B","8 T",field("B 실조제량","8"),"별도 확인","준비 중","예시 담당"]])}</section><section class="section-box"><div class="section-head"><h3>수행 메모</h3><small>실제 업무 상태를 변경하지 않음</small></div>${field("수행 메모","품목·수량·보관 정보를 확인한 후 수행합니다.",true)}</section>`;
 if(state.module==="billing")return intro+`<div class="filter-tabs"><b>청구 내역</b><span>결제 기록</span></div><section class="section-box"><div class="section-head"><h3>청구 항목</h3><small>가상 금액</small></div>${table(["청구서명","단가","수량","합계","조정","청구금액"],[["예시 진료","30,000원","1","30,000원","0원","30,000원"],["예시 검사","50,000원","1","50,000원","0원","50,000원"]])}<div class="summary-bar"><span>총 청구액 · 중앙에 항상 표시</span><b>80,000원</b></div></section><section class="section-box"><div class="section-head"><h3>결제 확인</h3><small>청구액·결제액·미수금 확인은 중앙에서</small></div><p class="prose">결제액 0원 · 미수금 80,000원</p>${field("수납 메모","예시 청구서를 확인하고 결제 수단을 선택합니다.",true)}<p class="panel-note">이 시안에는 실제 결제·환불 기능이 연결되어 있지 않습니다.</p></section>`;
 return intro+`<div class="filter-tabs"><button id="imaging-report" aria-pressed="${!state.viewer}">보고서</button><button id="imaging-viewer" aria-pressed="${state.viewer}">영상 보기</button></div>${state.viewer?`<section class="section-box"><div class="section-head"><h3>영상 확인 영역</h3><small>영상 보기에서는 넓게 보기 권장</small></div><div class="viewer-empty"><div><img src="assets/images.svg" alt=""><p>시안에 연결된 영상이 없습니다.<br>영상 확대·다중 비교에는 넓은 작업 영역을 사용합니다.</p></div></div></section>`:`<section class="section-box"><div class="section-head"><h3>영상검사 소견</h3><small>보고서 정리 모드</small></div><label class="field-label">검사 정보</label><p class="prose">예시 영상검사 · 가상 자료</p><label class="field-label">관찰 내용</label>${field("영상 관찰 내용","영상 자료를 확인한 후 관찰 내용을 작성합니다.",true)}<label class="field-label">종합소견</label>${field("영상 종합소견","다른 검사 결과와 함께 검토할 내용을 기록합니다.",true)}</section>`}<div class="callout">1,280px은 보고서·단일 자료 확인의 후보 폭. 진단 영상의 확대나 다중 영상 비교에는 이 제한을 강제하지 않아.</div>`;
}
function historyHtml(){return `<p class="panel-note">현재 환자의 ${modules[state.module].history}. 현재 입력은 바꾸지 않고 이전 기록을 참고해.</p><p class="history-label">2026. 09. 22</p><button class="history-card" data-history="1"><b>${state.module==="lab"?"혈청화학 검사":modules[state.module].task}</b><small>하루 · 예시 담당</small><p>이전 기록 · 검토 완료</p></button><p class="history-label">2026. 08. 29</p><button class="history-card" data-history="2"><b>${modules[state.module].task}</b><small>하루 · 예시 담당</small><p>이전 기록 · 검토 완료</p></button><div class="callout" class="history-preview">기록을 누르면 이 패널 안에서 예시 요약을 확인할 수 있어.</div>`;}
function receiptHtml(){
 if(state.module==="lab")return `<p class="panel-note">현재 요청에 연결된 장비 결과 · 가상 예시</p><button class="receipt-card" data-receipt="1"><span class="badge">현재 요청과 연결</span><b>예시 장비 A · 혈청화학</b><small>12:07 수신 · 4항목</small><p>검사 요청과 결과를 먼저 확인해.</p></button><button class="receipt-card" data-receipt="2"><span class="badge warn">확인 필요</span><b>예시 장비 B · 추가 결과</b><small>12:11 수신 · 가상 자료</small><p>연결 상태를 확인한 뒤 반영해.</p></button><div class="receipt-preview" hidden><div class="callout">가상 수신 결과 미리보기<br>칼슘 10.1 mg/dL · 알부민 3.3 g/dL</div><button data-apply="1">가상 입력에 반영</button></div><p class="panel-note">열기만 해서는 결과 입력이나 확정이 발생하지 않아.</p>`;
 if(state.module==="chart")return `<p class="panel-note">제안 역할 · 기존 차트에 동일한 오른쪽 패널이 있는 것은 아님</p><div class="receipt-card"><b>이번 진료의 참고 자료</b><small>가상 검사 결과 요약</small><p>요청 자료와 진료 기록을 함께 검토</p></div><p class="panel-note">이 자료를 열어도 진단·Order·차트 확정은 실행하지 않아.</p>`;
 if(state.module==="dispensing")return `<p class="panel-note">제안 역할 · 기존 수행 상세 흐름과 중복 여부를 검토해야 함</p><div class="receipt-card"><b>예시 조제품 A</b><p>예정량 10 mL<br>실조제량 10 mL<br>수행 전 확인 사항</p></div><p class="panel-note">처방·예정량·실제량은 가상 데이터. 패널을 열어도 수행 완료가 발생하지 않아.</p>`;
 if(state.module==="billing")return `<div class="receipt-card"><b>청구 확인 자료</b><p>예시 청구서 · 가상 금액<br>결제 내역과 메모를 검토</p></div><p class="panel-note">총 청구액·결제액·미수금·주요 결제 행동은 중앙에 남겨. 실제 수납 오른쪽 슬롯의 결제 기능을 이 시안대로 옮기는 것은 별도 설계가 필요해.</p>`;
 return `<div class="receipt-card"><b>종합소견·첨부</b><p>연결된 예시 첨부 0건</p></div><p class="panel-note">현재 영상 오른쪽 패널의 역할을 유지하며 작업 영역 안으로 배치하는 방향.</p>`;
}
function renderModule(){const m=modules[state.module];$("module").value=state.module;$("tab-name").textContent=m.label;$("queue-label").textContent=m.label;$("queue-task").textContent=m.task;$("document-title").textContent=m.title;$("history-title").textContent=m.history;$("history-toggle").setAttribute("aria-label",m.history+" 열기");$("receipt-title").textContent=m.right;$("receipt-toggle").querySelector("span").textContent=m.right;$("receipt-toggle").querySelector(".count").hidden=state.module!=="lab";$("document").innerHTML=documentHtml();$("history-content").innerHTML=historyHtml();$("receipt-content").innerHTML=receiptHtml();document.querySelectorAll("[data-module]").forEach(e=>e.classList.toggle("active",e.dataset.module===state.module));}
function closeModal(){if($("panel-dialog").open)$("panel-dialog").close();if(modalSide)state[modalSide]=false;modalSide=null;layout();if(previousFocus?.isConnected)previousFocus.focus();}
function openModal(side){const dialog=$("panel-dialog");modalSide=side;$("modal-title").textContent=side==="left"?modules[state.module].history:modules[state.module].right;$("modal-content").innerHTML=side==="left"?historyHtml():receiptHtml();if(!dialog.open){previousFocus=document.activeElement;dialog.showModal();}const r=$("workspace").getBoundingClientRect();dialog.style.margin="0";dialog.style.left=Math.max(12,r.right-dialog.offsetWidth-8)+"px";dialog.style.top=Math.min(innerHeight-dialog.offsetHeight-12,Math.max(12,$("work-area").getBoundingClientRect().top))+"px";}
function layout(animateWidth=false){
 $("viewport").value=state.vp;$("stage").style.width=state.vp+"px";
 state.scale=Math.min(1,$("stage-wrap").clientWidth/state.vp);$("stage").style.transform=`scale(${state.scale})`;$("stage-wrap").style.height=840*state.scale+"px";$("scale-label").textContent=`表示 ${Math.round(state.scale*100)}% · ${state.vp}px` .replace("表示","표시");
 $("app-shell").classList.toggle("queue-closed",!state.queue);$("queue").hidden=!state.queue;$("queue-open").hidden=state.queue;
 const legacy=state.current&&state.right;$("app-shell").classList.toggle("legacy-open",legacy);$("legacy-receipt").hidden=!legacy;
 const available=state.vp-(state.queue?382:94)-(legacy?326:0);let left=state.left&&!state.current,right=state.right&&!state.current,overlay=false;
 if(available-(left?280:0)-(right?336:0)<880&&(left||right)){
  overlay=true;const side=state.latest;state.left=side==="left";state.right=side==="right";left=false;right=false;
 }
 $("history-panel").hidden=!left;$("receipt-panel").hidden=!right;$("work-area").style.gridTemplateColumns=`${left?280:0}px minmax(0,1fr) ${right?336:0}px`;
 const centerElement=$("center"),centerStyle=getComputedStyle(centerElement);
 measuredCenterWidth=centerElement.clientWidth;
 const center=Math.max(0,centerElement.clientWidth-parseFloat(centerStyle.paddingLeft)-parseFloat(centerStyle.paddingRight));
 const hasWidthChoice=center>modules[state.module].cap;
 const cap=state.mode==="compact"?Math.min(modules[state.module].cap,center):center;
 $("document").classList.toggle("width-changing",animateWidth&&hasWidthChoice);$("document").style.setProperty("--doc-max",cap+"px");
 if(!hasWidthChoice&&document.activeElement===$("width-toggle"))$("receipt-toggle").focus({preventScroll:true});
 $("width-toggle").hidden=!hasWidthChoice;$("width-toggle").querySelector("span").textContent=state.mode==="compact"?"넓게 보기":"좁게 보기";$("width-toggle").setAttribute("aria-pressed",String(state.mode==="compact"));
 $("history-toggle").setAttribute("aria-expanded",String(state.left));$("receipt-toggle").setAttribute("aria-expanded",String(state.right));$("history-toggle").setAttribute("aria-controls",overlay&&state.left?"panel-dialog":"history-panel");$("receipt-toggle").setAttribute("aria-controls",overlay&&state.right?"panel-dialog":"receipt-panel");
 $("width-meter").textContent=`문서 ${Math.round(cap).toLocaleString()}px / 중앙 칸 ${centerElement.offsetWidth.toLocaleString()}px`;
 $("layout-mode").textContent=overlay?"보조 패널 1개 · 겹쳐 보기":left&&right?"이력 280 · 수신/참고 336":!hasWidthChoice?"폭 전환 없음 · 남은 폭 사용":state.mode==="compact"?"좁게 · 문서만 폭 제한":"넓게 · 남은 폭 사용";
 $("layout-summary").textContent=`${state.vp.toLocaleString()}px 화면 · 대기열 ${state.queue?"펼침":"접힘"} · 작업 영역 ${available.toLocaleString()}px · ${overlay?"패널은 겹쳐 표시, 중앙 폭 유지":left&&right?"양쪽 패널 동시 표시":"보조 패널 독립 표시"}`;
 $("layout-announcement").textContent=overlay?"공간이 좁아 최근에 연 패널 하나만 겹쳐 표시합니다. 이전 입력은 유지됩니다.":$("layout-summary").textContent;
 document.querySelectorAll("[data-preset]").forEach(e=>e.classList.toggle("active",e.dataset.preset===(state.current?"current":state.left&&state.right?"both":state.mode==="compact"&&!state.left&&!state.right?"focus":"")));
 if(overlay)openModal(state.latest);else if($("panel-dialog").open){$("panel-dialog").close();modalSide=null;}
}
function preset(kind){if($("panel-dialog").open)$("panel-dialog").close();modalSide=null;state.current=kind==="current";state.mode=state.current?"wide":"compact";state.left=kind==="both";state.right=kind==="both";state.latest="right";layout();}
function toast(msg){$("toast").textContent=msg;$("toast").hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$("toast").hidden=true,2800);}
$("module").addEventListener("change",e=>{if($("panel-dialog").open)$("panel-dialog").close();modalSide=null;state.module=e.target.value;state.left=state.right=false;state.current=false;state.viewer=false;renderModule();layout();});
$("viewport").addEventListener("change",e=>{state.vp=Number(e.target.value);layout();});
$("width-toggle").addEventListener("click",()=>{state.current=false;state.mode=state.mode==="compact"?"wide":"compact";layout(true);});
for(const [id,side] of [["history-toggle","left"],["receipt-toggle","right"]])$(id).addEventListener("click",()=>{state[side]=!state[side];state.latest=side;if(side==="left")state.current=false;layout();});
$("queue-close").addEventListener("click",()=>{state.queue=false;layout();});$("queue-open").addEventListener("click",()=>{state.queue=true;layout();});
document.addEventListener("input",e=>{if(e.target.dataset.field)fields[state.module+":"+e.target.dataset.field]=e.target.value;});
document.addEventListener("click",e=>{const el=e.target.closest("button");if(!el)return;if(el.dataset.preset)preset(el.dataset.preset);if(el.dataset.module){$("module").value=el.dataset.module;$("module").dispatchEvent(new Event("change"));}if(el.dataset.close){state[el.dataset.close]=false;layout();$(el.dataset.close==="left"?"history-toggle":"receipt-toggle").focus();}if(el.dataset.history){const root=el.closest(".panel-scroll");root.querySelector(".history-preview").textContent="가상 이전 기록 요약 · 현재 문서와 입력은 유지됩니다.";}if(el.dataset.receipt){const root=el.closest(".panel-scroll");root.querySelectorAll(".receipt-card").forEach(c=>c.classList.toggle("active",c===el));root.querySelector(".receipt-preview").hidden=false;}if(el.dataset.apply){fields["lab:칼슘 결과값"]="10.1";fields["lab:알부민 결과값"]="3.3";$("document").querySelector('[data-field="칼슘 결과값"]').value="10.1";$("document").querySelector('[data-field="알부민 결과값"]').value="3.3";toast("가상 결과만 입력에 반영했어. 실제 저장·확정은 실행하지 않아.");}if(el.id==="imaging-viewer"||el.id==="imaging-report"){state.viewer=el.id==="imaging-viewer";if(state.viewer)state.mode="wide";$("document").innerHTML=documentHtml();layout();}});
$("demo-save").addEventListener("click",()=>toast("시안에서 입력을 확인했어. 서버로 전송되지 않아."));
$("modal-close").addEventListener("click",closeModal);$("panel-dialog").addEventListener("cancel",e=>{e.preventDefault();closeModal();});
$("panel-dialog").addEventListener("click",e=>{const r=e.currentTarget.getBoundingClientRect();if(e.target===e.currentTarget&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))closeModal();});
for(const id of ["profile","patient-profile"])$(id).addEventListener("click",()=>$("profile-dialog").showModal());$("profile-close").addEventListener("click",()=>$("profile-dialog").close());
new ResizeObserver(()=>layout()).observe($("stage-wrap"));
new ResizeObserver(()=>{if($("center").clientWidth!==measuredCenterWidth)layout();}).observe($("center"));
renderModule();preset(["current","both"].includes(params.get("state"))?params.get("state"):"focus");
